/// <summary>
/// When <c>WHSWorkExecuteDisplayClusterPutawayPassedClusterPutAddButtonsFlight</c> is enabled,
/// logic that adds buttons will be executed after put cluster process in case the cluster was previously passed.
/// </summary>
internal final class WHSWorkExecuteDisplayClusterPutawayPassedClusterPutAddButtonsFlight extends Flight
{
    private static WHSWorkExecuteDisplayClusterPutawayPassedClusterPutAddButtonsFlight singleton = new WHSWorkExecuteDisplayClusterPutawayPassedClusterPutAddButtonsFlight();
 
}
